      "ballot_id": "B030",
      "proposed_laureates": ["Francis Halzen"],
      "assessment": {
        "nobel_worthiness": "High-energy neutrino astronomy opened a genuinely new observational window on the violent universe.",
        "attribution": "Halzen supplied sustained scientific leadership for IceCube and is a credible individual representative of the discovery.",
        "maturity": "Astrophysical neutrinos are securely established and have progressed from diffuse flux to identified sources.",
        "uncertainties": ["The decisive work was necessarily a large-collaboration achievement, making individual attribution intrinsically incomplete."]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B014",
      "proposed_laureates": ["Hidetoshi Katori", "Jun Ye"],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision measurement and enable stringent tests of fundamental physics.",
        "attribution": "Katori and Ye made distinct, central contributions to the lattice-clock concept and its experimental realization.",
        "maturity": "The performance, reproducibility, and scientific uses of these clocks are well established.",
        "uncertainties": ["The eventual scope of a prize must distinguish lattice clocks from the broader history of optical frequency metrology."]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B045",
      "proposed_laureates": ["Enrico Costa", "Filippo Frontera", "Shrinivas R. Kulkarni"],
      "assessment": {
        "nobel_worthiness": "Afterglow localization changed gamma-ray bursts from enigmatic flashes into a cosmological astrophysical field.",
        "attribution": "Costa and Frontera were central to the enabling X-ray observations, while Kulkarni was decisive in optical follow-up and interpretation.",
        "maturity": "The afterglow framework has been repeatedly confirmed over decades and remains foundational.",
        "uncertainties": ["Credit is distributed across the BeppoSAX team and rapid multi-observatory follow-up community."]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B003",
      "proposed_laureates": ["Jian-Wei Pan", "Nicolas Gisin"],
      "assessment": {
        "nobel_worthiness": "Long-distance quantum communication made entanglement and quantum-state transfer practical at scales relevant to networks.",
        "attribution": "Gisin's pioneering fibre and free-space work and Pan's landmark long-distance and satellite demonstrations are central contributions.",
        "maturity": "The underlying effects and key demonstrations are robust, independently reproduced, and technologically consequential.",
        "uncertainties": ["The boundary between this achievement, quantum teleportation, and quantum key distribution requires careful definition."]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B007",
      "proposed_laureates": ["Federico Capasso", "Jérôme Faist"],
      "assessment": {
        "nobel_worthiness": "Quantum cascade lasers created a powerful semiconductor source across important infrared and terahertz spectral regions.",
        "attribution": "Capasso developed the key band-structure engineering approach and Faist led the first successful device demonstration.",
        "maturity": "Their physical principle and broad practical deployment have been proven over many years.",
        "uncertainties": ["The appropriate division of credit among the foundational heterostructure and device contributors needs detailed review."]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B026",
      "proposed_laureates": ["Eli Yablonovitch", "John D. Joannopoulos", "Sajeev John"],
      "assessment": {
        "nobel_worthiness": "Photonic crystals established control of light through periodic media and reshaped nanophotonics.",
        "attribution": "Yablonovitch, Joannopoulos, and John supplied the essential experimental, conceptual, and theoretical foundations.",
        "maturity": "The band-gap physics is secure and its influence on photonics is deep and durable.",
        "uncertainties": ["Applications are diverse, so the prize formulation should retain a clear focus on the fundamental photonic-band-gap discovery."]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B025",
      "proposed_laureates": ["Daniel J. Eisenstein", "Shaun Cole", "Will J. Percival"],
      "assessment": {
        "nobel_worthiness": "Baryon acoustic oscillations furnished a precise and independent standard ruler for observational cosmology.",
        "attribution": "These scientists led formative survey analyses that established BAO as a practical cosmological measurement.",
        "maturity": "The signal has been confirmed across multiple surveys and is integral to the modern cosmological parameter framework.",
        "uncertainties": ["The theoretical origin, survey infrastructure, and later measurements involve many further indispensable contributors."]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B022",
      "proposed_laureates": ["Maura McLaughlin", "Michael Kramer", "Richard N. Manchester"],
      "assessment": {
        "nobel_worthiness": "The nanohertz gravitational-wave background is a major extension of gravitational-wave astronomy using a wholly different detector scale.",
        "attribution": "The named pulsar-timing leaders are plausible representatives, but the discovery rests on several international timing arrays.",
        "maturity": "The correlated background evidence is strong and mutually supported by independent PTA collaborations, though source-level characterization is early.",
        "uncertainties": ["Longer data sets are needed to refine the spectral interpretation and establish the astrophysical origin beyond residual alternatives.", "Attribution across international collaborations is unusually difficult."]
      }
    }
  ]
